def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.
    Each cell's value can be collected at most once, even if both paths pass through it.
    """
    if N <= 0:
        raise ValueError("Grid size N must be positive")

    # Build grid with 1-indexed coordinates
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    # Special case: single cell grid
    if N == 1:
        return grid[1][1]

    # Initialize DP arrays
    # dp[i1][i2] represents max sum when first path at (i1, k-i1) and second at (i2, k-i2)
    # Use -inf for impossible states
    NEG_INF = -10**18
    dp = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = grid[1][1]  # both start at (1,1), count once

    # Iterate over all possible sums of coordinates k = i + j
    for k in range(3, 2 * N + 1):
        dp_next = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
        i_min = max(1, k - N)
        i_max = min(N, k - 1)
        for i1 in range(i_min, i_max + 1):
            j1 = k - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = k - i2
                if j2 < 1 or j2 > N:
                    continue
                # Compute best previous state
                best_prev = NEG_INF
                for di1 in (0, 1):  # 0: came from left (i1-1), 1: came from up (i1)
                    for di2 in (0, 1):
                        pi1 = i1 - di1
                        pi2 = i2 - di2
                        if pi1 < 1 or pi2 < 1:
                            continue
                        prev_val = dp[pi1][pi2]
                        if prev_val > best_prev:
                            best_prev = prev_val
                if best_prev == NEG_INF:
                    continue
                # Add current cell values, avoid double counting if same cell
                add = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    add += grid[i2][j2]
                dp_next[i1][i2] = best_prev + add
        dp = dp_next

    return dp[N][N] if dp[N][N] != NEG_INF else 0

def max_product(num_str: str, N: int, K: int) -> int:
    """
    Returns the maximum product obtainable by inserting K multiplication signs into the
    numeric string `num_str` of length N. The string must consist only of digits.
    """
    # Input validation
    if not isinstance(num_str, str) or not num_str.isdigit():
        raise ValueError("num_str must be a string of digits")
    if len(num_str) != N:
        raise ValueError("Length of num_str does not match N")
    if K < 0:
        raise ValueError("K must be non-negative")
    if K > N - 1:
        # Impossible to insert more than N-1 multiplication signs
        return 0

    # Precompute integer values for all substrings
    sub_int = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(N):
        val = 0
        for j in range(i + 1, N + 1):
            val = val * 10 + int(num_str[j - 1])
            sub_int[i][j] = val

    # DP table: dp[i][k] = max product for prefix of length i with k multiplications
    dp = [[-1] * (K + 1) for _ in range(N + 1)]

    # Base case: no multiplication signs
    for i in range(1, N + 1):
        dp[i][0] = sub_int[0][i]

    # Fill DP table
    for k in range(1, K + 1):
        for i in range(k + 1, N + 1):  # need at least k+1 digits to place k signs
            best = -1
            for j in range(k, i):
                if dp[j][k - 1] != -1:
                    prod = dp[j][k - 1] * sub_int[j][i]
                    if prod > best:
                        best = prod
            dp[i][k] = best

    return dp[N][K] if dp[N][K] != -1 else 0

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    terms = []
    first_term = True
    for degree, coeff in zip(range(n, -1, -1), coeffs):
        if coeff == 0:
            continue

        # Determine sign
        if first_term:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'

        abs_coeff = abs(coeff)

        # Determine coefficient string
        if abs_coeff == 1 and degree > 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)

        # Determine variable part
        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''

        term = f"{sign}{coeff_str}{var_str}"
        terms.append(term)
        first_term = False

    if not terms:
        return '0'
    return ''.join(terms)

